update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p066","body":"نشیب و فراز دن کے شبِ ظلمت میں ڈھنس گئے\nخودی کا سبق دے کر شاہین قفس گئے\n\nاس دل کی کیا کہیں اس دل کی تھی بات الگ\nجب جب اس پہ ضرب  لگیں لب یونہی ہنس گئے\n\nایسی بھی کیا فرصتیں ایسی بھی کیا مجبوریاں\nہم خود سے خلوت  کو خود ہی ترس گئے\n\nعمر بھر کی فرقت میں تھے وصل کے چار دن\nکچھ وقت ابر چھائے رہے پھر وہ بھی برس گئے\n\nاحمد ؔ ہماری ہر بات رد ہماری ہر کاوش فضول\nہم آپ کی حمایت میں آپ ہی سے ڈس گئے"},{"slug":"tum-p067","body":"کیا کہوں کہ زندگی کس طرح بسر ہوئی\nدن فرصت نظر ہوا شب فرقت نظر ہوئی"},{"slug":"tum-p068","body":"نہ ستاروں کی جگمگاہٹ آج نہ چاند کی چاندنی آئی\nدل کی ویرانیوں سے ہوتی ہوئی اک یاد پرانی آئی\n\nپھر سے جو ہوئی دریچے میں اک خواب کی آہٹ\nاحمد ؔ نئی شمع تو جلا لی پر پرانی نہ بجھانی آئی"},{"slug":"tum-p069","body":"کس طرح سے آج یہ ہوا چلنے لگی ہے\nدل میں بجھی  جو آس تھی وہ بھڑک اٹھی ہے\n\nسپنے بھی شب وروز یوں أنے لگے ہیں\nجیسے یہ محبت آج بھی نئی نئی ہے\n\nتجھ سے ہجر اب کاٹے بھی نہیں کٹنے دیتا\nتجھ سے بچھڑے کو جیسے اک رات ہوئی ہے\n\nعجب ہے میرے شوق کا یہ عالم بھی\nمجھ کو تو بےدلی کی عادت رہی ہے\n\nدل نے چاہا اول تجھے پرایا ہی نہ کریں\nپر اس دل کی آخر کس نے سنی ہے\n\nاحمد ؔ  تو بھی تو لوٹ کے آتا کبھی تو\nتو نے بھی تو آخر محبت کی ہے"},{"slug":"tum-p070","body":"محبت تو ہے قفس اور ہے رہائی\nیہی سزا ہے اور یہی مسیحائی\n\nشب کی  ٹھہری پچھلی پہر میں\nہے چھبتی ہوئی سی گھپ تنہائی\n\nسلگتے دل کے کسی ویراں کونے سے\nاک بھولی ہوئی سی کوئی یاد آئی\n\nخواب بھی اب وہ خواب کہاں\nخواب نے بھی حقیقت دکھائی\n\nبادل بھی گرجے ، گھٹا بھی برسی\nدل بھی دھڑکا اور شمع جلائی\n\nکیوں اسی پہ اس بار پھر آیا  دل\nکیوں یاد نہ آئی ہمیں رسم بےوفائی\n\nتیرے بعد بھی احمد   ہم نے جسے چاہا\nجاناں وہی دل دہائی ، وہی مقدر جدائی"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
